from netmiko import ConnectHandler
from netmiko.exceptions import NetmikoTimeoutException, NetmikoAuthenticationException
for ip in ['10.1.1.1', '10.1.1.2']:
    try:
        conn = ConnectHandler(device_type='cisco_ios', host=ip,
                              username='admin', password='Cisco123')
    except NetmikoTimeoutException:
        print(f'{ip}: timeout')
    except NetmikoAuthenticationException:
        print(f'{ip}: sai mật khẩu')
    except Exception as e:
        print(f'{ip}: lỗi khác {e}')
    else:
        print(conn.send_command('show version | include uptime'))
        conn.disconnect()
    finally:
        print(f'{ip}: xong')

import requests, json
url = 'https://10.1.1.1/restconf/data/ietf-interfaces:interfaces'
headers = {'Accept': 'application/yang-data+json'}
r = requests.get(url, headers=headers, auth=('admin', 'Cisco123'),
                 verify=False, timeout=10)
if r.status_code == 200:
    data = r.json()
    for intf in data['ietf-interfaces:interfaces']['interface']:
        print(intf['name'], intf.get('description', '-'))
else:
    print('Lỗi', r.status_code, r.text)

